  /// Timestamp when the current measurement window started.
  window_start_time DateTime @db.Timestamptz

  /// Whether this rate limiting rule is currently active and enforced.
  is_enabled Boolean

  /// Detailed description of this rate limiting rule's purpose and usage.
  description String?

  /// Timestamp when this rate limiting rule was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this rate limiting rule was last modified.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([rate_limit_type, scope_identifier])
  // spellchecker: ignore-next-line
  @@index([rate_limit_type, scope_identifier, is_enabled], map: "todo_app_api_rate_limits_rate_limit_type_scope_identif_0bb3c0de")
  @@index([window_start_time])
  @@index([is_enabled])
}

/// System health monitoring and status tracking for availability monitoring.
