import { authorize_user_login } from "../../../authorize/authorize_user_login";
import { authorize_user_refresh } from "../../../authorize/authorize_user_refresh";

export async function test_api_user_profile_privacy_isolation(
  connection: api.IConnection,
): Promise<void> {
  // Create first user account
  const firstUserConnection: api.IConnection = { host: connection.host };
  const firstUser = await authorize_user_join(firstUserConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(firstUser);
  // Create second user account
  const secondUserConnection: api.IConnection = { host: connection.host };
  const secondUser = await authorize_user_join(secondUserConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
    } satisfies ITodoAppUser.IJoin,
  });
  typia.assert(secondUser);
  // First user updates their own profile
  const newDisplayName = RandomGenerator.name();
  const firstUserUpdate = await api.functional.todoApp.user.profile.update(
    firstUserConnection,
    {
      body: {
        display_name: newDisplayName,
      } satisfies ITodoAppUser.IUpdate,
    },
  );
  typia.assert(firstUserUpdate);
  // Verify first user's update was successful
  TestValidator.equals(
    "first user display name updated correctly",
    firstUserUpdate.display_name,
    newDisplayName,
  );
  // Second user attempts to update first user's profile using second user's connection - should fail
  await TestValidator.error(
    "second user cannot update first user's profile",
    async () => {
      await api.functional.todoApp.user.profile.update(secondUserConnection, {
        body: {
          display_name: RandomGenerator.name(),
        } satisfies ITodoAppUser.IUpdate,
      });
    },
  );
  // Verify profiles remain isolated
  TestValidator.notEquals(
    "user IDs should be different",
    firstUser.id,
    secondUser.id,
  );
  TestValidator.notEquals(
    "user emails should be different",
    firstUser.email,
    secondUser.email,
  );
  // Verify first user's profile remains unchanged after failed cross-user update attempt
  const firstUserProfileAfterAttempt =
    await api.functional.todoApp.user.profile.update(firstUserConnection, {
      body: {
        display_name: firstUserUpdate.display_name,
      } satisfies ITodoAppUser.IUpdate,
    });
  typia.assert(firstUserProfileAfterAttempt);
  TestValidator.equals(
    "first user profile remains unchanged after cross-user attempt",
    firstUserProfileAfterAttempt.display_name,
    newDisplayName,
  );
}

